import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const selfDir = path.dirname(fileURLToPath(import.meta.url));
const pkgRoot = path.resolve(selfDir, '..');
const root = path.resolve(pkgRoot, '..', '..');
const srcDir = path.join(pkgRoot, 'src');
const i18nDir = path.join(srcDir, 'i18n');

let pass = 0, fail = 0;
const fails = [];
const check = (label, ok) => { if (ok) pass++; else { fail++; fails.push(label); } };

const zh = JSON.parse(fs.readFileSync(path.join(i18nDir, 'zh-CN.json'), 'utf8'));
const locales = fs.readdirSync(i18nDir).filter((f) => f.endsWith('.json')).map((f) => f.replace(/\.json$/, '')).sort();
const packs = {};
for (const f of locales) packs[f] = JSON.parse(fs.readFileSync(path.join(i18nDir, f + '.json'), 'utf8'));
const keys = Object.keys(zh).sort();
const appJs = fs.readFileSync(path.join(srcDir, 'renderer', 'app.js'), 'utf8');
const emTs = fs.readFileSync(path.join(srcDir, 'electron-main.ts'), 'utf8');
const pre = fs.readFileSync(path.join(srcDir, 'preload.cjs'), 'utf8');
const idx = fs.readFileSync(path.join(srcDir, 'renderer', 'index.html'), 'utf8');
const suite = fs.readFileSync(path.join(root, 'scripts', 'full-verify-rounds.mjs'), 'utf8');
const css1 = fs.readFileSync(path.join(srcDir, 'renderer', 'app.css'), 'utf8');
const css2 = fs.readFileSync(path.join(srcDir, 'renderer', 'renderer.css'), 'utf8');
const selectors = (s) => { const t = s.replace(/\/\*[\s\S]*?\*\//g, ''); const out = new Set(); let m; const re = /([^{}]+)\{/g; while ((m = re.exec(t))) { const head = m[1].trim(); if (!head || head.startsWith('@')) continue; for (const sel of head.split(',')) { const x = sel.trim(); if (x) out.add(x); } } return out; };
const s1 = selectors(css1), s2 = selectors(css2);
const used = new Set([...(appJs + emTs).matchAll(/\b(?:t|tOr|tMain)\(\s*'([a-zA-Z0-9_.]+)'/g)].map((x) => x[1]));
const dataI18n = new Set([...idx.matchAll(/data-i18n(?:-title|-placeholder|-aria)?="([a-zA-Z0-9_.]+)"/g)].map((x) => x[1]));
const hooks = new Set([...appJs.matchAll(/window\.(\__\w+)\s*=/g)].map((x) => x[1]));
const chans = new Set([...pre.matchAll(/ipcRenderer\.(?:invoke|send|on)\('([\w:]+)'/g)].map((x) => x[1]));
const files = [];
(function walk(d){ for (const f of fs.readdirSync(d)) { const p = path.join(d, f); const st = fs.statSync(p); if (st.isDirectory()) walk(p); else if (/\.(ts|js|cjs|css|html)$/.test(f)) files.push(path.relative(root, p).split(path.sep).join('/')); } })(srcDir);
const gates = fs.readdirSync(path.join(pkgRoot, 'scripts')).filter((f) => f.startsWith('verify-') && f.endsWith('.mjs')).sort();

